#!/usr/bin/env bash
# Question 5: Ready only if the Service answers. Generated by Quick Create; variables arrive as environment variables.
set -euo pipefail

kubectl create namespace "${Q5_NS}" >/dev/null 2>&1 || kubectl get namespace "${Q5_NS}" >/dev/null
timeout 60 bash -c "until kubectl -n '${Q5_NS}' get serviceaccount default >/dev/null 2>&1; do sleep 1; done"
kubectl -n "${Q5_NS}" delete pod gatekeeper backend --ignore-not-found --wait=true >/dev/null
kubectl -n "${Q5_NS}" apply -f - <<< '{"apiVersion":"v1","kind":"Service","metadata":{"name":"checkout-api"},"spec":{"selector":{"role":"checkout-backend"},"ports":[{"port":80}]}}' >/dev/null
: "${Q5_NS}" "${Q5_NODE}"
